s='_DRG_ZDR_BZD_GBZ_RGB'
opts={'A':'ZBGRB','B':'ZBGRD','C':'BBGRD','D':'ZBDRD'}
def fill(o):
    t=list(s);it=iter(o)
    for i,c in enumerate(t):
        if c=='_':t[i]=next(it)
    t=''.join(t)
    return all(t[i:i+5]=='ZDRGB' for i in range(0,20,5))
ok=[k for k,v in opts.items() if fill(v)]
assert ok==['B']

