rel={'wife':'F','G':'brother of wife'}
assert rel['G']=='brother of wife'
o={'A':'Brother’s wife','B':'Sister’s husband','C':'Husband’s sister','D':'Wife’s brother'}
r='Wife’s brother'
assert r==o['D'] and all(r!=o[k] for k in 'ABC')

